/bin/sh -lc "node --input-type=module - <<'EOF'
import { chromium } from 'playwright';
import { pathToFileURL } from 'node:url';
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 360, height: 800 } });
await page.goto(pathToFileURL(process.cwd() + '/dist/index.html').href);
console.log(await page.locator('.card').first().evaluate(el => ({width: el.getBoundingClientRect().width, height: el.getBoundingClientRect().height})));
await page.screenshot({ path: '/tmp/neon-pairs.png', fullPage: true });
await browser.close();
EOF"

